/// Every operation and resource of the Lowco API.
class GeneratedClient {
  GeneratedClient(Core core)
      : barcode = BarcodeOperations(core),
        docai = DocaiOperations(core),
        ocr = OcrOperations(core),
        pdf = PdfOperations(core),
        qr = QrOperations(core),
        render = RenderOperations(core),
        verify = VerifyOperations(core),
        audit = AuditResource(core),
        files = FilesResource(core),
        jobs = JobsResource(core),
        keys = KeysResource(core),
        messageTemplates = MessageTemplatesResource(core),
        messages = MessagesResource(core),
        otp = OtpResource(core),
        requests = RequestsResource(core),
        senders = SendersResource(core),
        settings = SettingsResource(core),
        sign = SignResource(core),
        signTemplates = SignTemplatesResource(core),
        suppressions = SuppressionsResource(core),
        templates = TemplatesResource(core),
        usage = UsageResource(core),
        webhooks = WebhooksResource(core);

  /// /v1/barcode operations.
  final BarcodeOperations barcode;

  /// /v1/docai operations.
  final DocaiOperations docai;

  /// /v1/ocr operations.
  final OcrOperations ocr;

  /// /v1/pdf operations.
  final PdfOperations pdf;

  /// /v1/qr operations.
  final QrOperations qr;

  /// /v1/render operations.
  final RenderOperations render;

  /// /v1/verify operations.
  final VerifyOperations verify;

  /// Console audit log.
  final AuditResource audit;

  /// Uploaded and produced files.
  final FilesResource files;

  /// Asynchronous jobs.
  final JobsResource jobs;

  /// .
  final KeysResource keys;

  /// .
  final MessageTemplatesResource messageTemplates;

  /// .
  final MessagesResource messages;

  /// .
  final OtpResource otp;

  /// .
  final RequestsResource requests;

  /// .
  final SendersResource senders;

  /// Environment settings.
  final SettingsResource settings;

  /// .
  final SignResource sign;

  /// .
  final SignTemplatesResource signTemplates;

  /// .
  final SuppressionsResource suppressions;

  /// Stored render templates.
  final TemplatesResource templates;

  /// Usage and balance.
  final UsageResource usage;

  /// Webhook endpoints and deliveries.
  final WebhooksResource webhooks;

}
